function q(s){ return String(s==null?'':s).replace(/'/g, "''"); }
const app = $('Applications Needing Prep').item.json;
let pkg = {}; const r = $json.response || '';
try { pkg = JSON.parse(r); } catch(e) { const m = r.match(/\{[\s\S]*\}/); if (m) { try { pkg = JSON.parse(m[0]); } catch(_){} } }
const payload = q(JSON.stringify(pkg));
const query = `INSERT INTO app.interview_prep (application_id, package) VALUES ('${app.app_id}', '${payload}'::jsonb);`;
const text = `Interview prep — ${app.title} @ ${app.company_name}

Company: ${pkg.company_research || ''}

Likely questions:
- ${(pkg.likely_questions||[]).join('
- ')}

Talking points:
- ${(pkg.talking_points||[]).join('
- ')}

Ask them:
- ${(pkg.questions_to_ask||[]).join('
- ')}`;
return [{ json: { query, text, title: app.title, company: app.company_name } }];
